-- 104. THE CLERIC LIST: 6th THROUGH 9th.
--
-- The last third, and the list is complete at 106 spells. Same
-- contract as 102 and 103.

insert into spells
  (key, name, roll_name, level, cast_type, category, school, save_ability,
   dice, concentration, ritual, range, duration, casting_time,
   components, material, classes, description)
values
-- ================================ 6th ================================
('sp_bladebarrier','Blade Barrier','Blade Barrier',6,'Save','6th Circle','evocation','dex',
 '6d10',true,false,'90 feet','Up to 10 minutes','1 action',array['v','s'],null,array['cleric'],
 'A wall of whirling blades, straight or ringed. Passing through costs 6d10 slashing, halved on a Dexterity save, and the whole wall is difficult terrain.'),
('sp_createundead','Create Undead','Create Undead',6,'Utility','6th Circle','necromancy',null,
 null,false,false,'10 feet','Instantaneous','1 minute',array['v','s','m'],'a black onyx stone worth 150 gp for each corpse, and an alchemical vial',array['cleric','warlock','wizard'],
 'Up to three corpses become ghouls under your command for 24 hours, renewed by recasting. Cast at night only. A bigger slot makes stronger undead.'),
('sp_findthepath','Find the Path','Find the Path',6,'Utility','6th Circle','divination',null,
 null,true,false,'Self','Up to 1 day','1 minute',array['v','s','m'],'divinatory tools worth 100 gp and an object from the destination',array['cleric','bard','druid'],
 'You know the shortest route to a place you are familiar with on the same plane, and which way it lies at all times.'),
('sp_forbiddance','Forbiddance','Forbiddance',6,'Utility','6th Circle','abjuration',null,
 '5d10',false,true,'Touch','1 day','10 minutes',array['v','s','m'],'holy water, incense and powdered ruby worth 1,000 gp',array['cleric'],
 'An area is warded against teleport and planar travel, and a chosen creature type takes 5d10 radiant or necrotic entering it. Cast daily for 30 days and it becomes permanent.'),
('sp_harm','Harm','Harm',6,'Save','6th Circle','necromancy','con',
 '14d6',false,false,'60 feet','Instantaneous','1 action',array['v','s'],null,array['cleric'],
 '14d6 necrotic on a failed Constitution save, half on a success - and on a failure the maximum drops by the same amount for an hour. It cannot reduce below 1.'),
('sp_heal','Heal','Heal',6,'Heal','6th Circle','evocation',null,
 null,false,false,'60 feet','Instantaneous','1 action',array['v','s'],null,array['cleric','druid'],
 '70 hit points restored, and blindness, deafness and every disease ended. Nothing for a construct or the undead. Ten more per slot level above 6th.'),
('sp_heroesfeast','Heroes'' Feast','Heroes'' Feast',6,'Heal','6th Circle','conjuration',null,
 '2d10',false,false,'30 feet','Instantaneous','10 minutes',array['v','s','m'],'a gem-encrusted bowl worth 1,000 gp, consumed',array['cleric','druid'],
 'A feast for twelve, taking an hour to eat. For 24 hours each diner is cured of disease and poison, immune to both and to being frightened, has advantage on Wisdom saves, and gains 2d10 maximum and current hit points.'),
('sp_planarally','Planar Ally','Planar Ally',6,'Utility','6th Circle','conjuration',null,
 null,false,false,'60 feet','Instantaneous','10 minutes',array['v','s'],null,array['cleric'],
 'You call on your deity and a celestial, elemental or fiend of their choosing appears. It is not compelled to serve - it will name a price, and the DM decides what.'),
('sp_trueseeing','True Seeing','True Seeing',6,'Utility','6th Circle','divination',null,
 null,false,false,'Touch','1 hour','1 action',array['v','s','m'],'an ointment for the eyes worth 25 gp, consumed',array['cleric','bard','sorcerer','warlock','wizard'],
 'For an hour the creature has truesight to 120 feet: it sees the invisible, through illusions and shapechanges, into the Ethereal, and in the dark.'),
('sp_wordofrecall','Word of Recall','Word of Recall',6,'Utility','6th Circle','conjuration',null,
 null,false,false,'5 feet','Instantaneous','1 action',array['v'],null,array['cleric'],
 'You and up to five willing creatures teleport instantly to a sanctuary you designated beforehand.'),

