('sp_trueresurrection','True Resurrection','True Resurrection',9,'Heal','9th Circle','necromancy',null,
 null,false,false,'Touch','Instantaneous','1 hour',array['v','s','m'],'holy water and diamonds worth 25,000 gp, consumed',array['cleric','druid'],
